sys_variable_value.value:
(function execute(inputs, outputs) {
   var fieldMapping = {
       "v_ano": "ano",
       "v_selic": "selic",
       "v_tr": "tr",
       "v_tjlp": "tjlp",
       "v_cdi": "cdi",
       "v_dolar_sofr": "dolar",
       "v_coeficiente_de_atualizacao_monetaria": "coeficiente"
   };


   var grMultiRow = new GlideRecord('sc_multi_row_question_answer');
   grMultiRow.addEncodedQuery('row_index=' + inputs.row_index + '^parent_id=' + inputs.parent_id);
   grMultiRow.query();

   while (grMultiRow.next()) {
       var questionName = grMultiRow.item_option_new.name;
       var value = grMultiRow.getValue('value');

       if (fieldMapping[questionName]) {
           fieldMapping[questionName] = value;
       }
   }

outputs.ano = fieldMapping['v_ano'];
outputs.selic = fieldMapping['v_selic'];
outputs.tr = fieldMapping['v_tr'];
outputs.tjlp = fieldMapping['v_tjlp'];
outputs.cdi = fieldMapping['v_cdi'];
outputs.dolar = fieldMapping['v_dolar_sofr'];
outputs.coeficiente = fieldMapping['v_coeficiente_de_atualizacao_monetaria'];

})(inputs, outputs);

